 list:()=>X.ctl().map(c=>c.id),
 get:id=>{const c=X.ctlById(id);if(!c)return null;const nd=X.nextDue(c),t=X.tst().find(x=>x.ctl===id),rk=arr(c.risks).map(x=>X.riskById(x)).filter(Boolean),fn=X.fnd().filter(f=>f.ctl===id&&X.open(f));
  return{title:c.t,status:c.res,tone:c.res==="Effective"?"good":c.res==="Not tested"?"mute":c.res==="Ineffective"?"bad":"warn",owner:c.own,backup:c.bak,tags:c.maps.map(m=>m.split(":")[0].toLowerCase()).filter((x,i,a)=>a.indexOf(x)===i),
   fields:[F("ref","Reference",c.ref),F("maps","Mapped to",c.maps.join("; ")),F("src","Where defined",c.src),F("freq","Test frequency",c.freq,{type:"select",opts:["Monthly","Quarterly","Semiannual","Annual"]}),F("last","Last tested",date(c.last)),F("next","Next test due",date(nd)+" ("+(days(nd)<0?Math.abs(days(nd))+" days overdue":"in "+days(nd)+" days")+")"),F("cycle","This cycle",t?t.st+(t.res?", "+t.res:""):"Not in the Q4 cycle"),F("pol","Policy",c.pol||"-"),F("ent","Data entity",c.ent||"-")],
   actions:[{id:"test",l:"Record test result",cls:"primary"},{id:"evidence",l:"Request evidence",cls:"quiet"},{id:"finding",l:"Raise a finding",cls:"quiet"}],
   links:[grp("Risks this control treats",rk.map(r=>go2(r.id,r.t,r.cat))),grp("Open findings",fn.map(f=>go2(f.id,f.t,f.st))),c.pol?grp("Policy",[go2(c.pol,"Policy "+c.pol)]):null,grp("Process and metric",[{id:"grc.control_test",t:"Control test process",sub:"Process",tag:"process",st:"info",go:()=>G(()=>PROCLIB.open("grc.control_test"))},{id:c.met,t:(METRICS[c.met]||{n:c.met}).n,sub:"Metric",tag:c.met,st:"info",go:()=>go("metrics",c.met)}])].filter(Boolean),
   extra:`<div><b class="small">Evidence (linked records, not uploads)</b>${c.ev.length?`<ul class="grc-ev">${c.ev.map(e=>`<li>${link(e[1],e[0])} <span class="muted small">${H(e[1])}</span></li>`).join("")}</ul>`:'<p class="muted small">No evidence linked. Use Request evidence or attach a record in the Attachments tab.</p>'}</div>`}},
 set:(id,k,v)=>{const c=X.ctlById(id);if(!c)return false;const m={owner:"own",backup:"bak",freq:"freq"}[k];if(!m)return false;c[m]=v;X.put("control",c);sync();return true},
