   fields:[F("sev","Severity",f.sev,{type:"select",opts:["Critical","High","Medium","Low"]}),F("src","Source",f.src+" "+f.sref),F("ctl","Control",f.ctl||"-"),F("risk","Risk",f.risk||"-"),F("vend","Vendor",f.vend||"-"),F("due","Due",f.due,{type:"date"}),F("age","Open for",Math.abs(days(f.opened))+" days"),F("plan","Remediation plan",f.steps.length?done+" of "+f.steps.length+" steps done":"No plan yet"),F("debt","Technical debt",f.debt&&f.debt!=="yes"?f.debt:f.debt==="yes"?"Tracked in the debt ledger":"Not in the ledger"),F("desc","Detail",f.desc)],
