function newRisk(){openForm({id:"grc_risk_new",title:"Add an enterprise risk",story:"The risk joins the unified register beside project risks. It is scored on one 5 by 5 scale and compared with the appetite for its category.",submit:"Add risk",
 fields:[{section:"The risk"},{k:"t",label:"Risk statement",type:"text",req:true,ph:"Cause, event, effect"},{k:"cat",label:"Category",type:"select",opts:X.cats().filter(c=>c!=="Project"),req:true},{k:"own",label:"Owner",type:"people",req:true},{k:"bak",label:"Backup",type:"people",req:true,help:"A different named person"},
  {section:"Score"},{k:"il",label:"Inherent likelihood (1 to 5)",type:"range",min:1,max:5},{k:"ii",label:"Inherent impact (1 to 5)",type:"range",min:1,max:5},{k:"rl",label:"Residual likelihood (1 to 5)",type:"range",min:1,max:5},{k:"ri",label:"Residual impact (1 to 5)",type:"range",min:1,max:5},
  {section:"Treatment"},{k:"plan",label:"Treatment plan",type:"longtext"},{k:"ctl",label:"Controls that treat it",type:"multi",opts:X.ctl().map(c=>[c.id,c.ref+" "+c.t])},{k:"due",label:"Next review",type:"date"}],
 defaults:{cat:"Cyber",il:3,ii:3,rl:2,ri:3,due:iso(60),own:X.who("Rina Okafor",0),bak:X.who("Theo Marlowe",1)},
 live:v=>{const a=X.score(v.rl,v.ri),ap=X.app()[v.cat];return `<p class="small"><b>Residual ${a}</b> (${X.band(a)[1]}). Appetite for ${H(v.cat||"")}: ${ap!=null?ap+(a>ap?", so this is above appetite and needs treatment or an approved acceptance":", so it is within appetite"):"not set"}.</p>`},
 onSubmit:v=>{if(v.own===v.bak){toast("The backup must be a different person","warn");return}const id="GR-"+(113+X.rk().length-12);
  const r={id,t:v.t,cat:v.cat,own:v.own,bak:v.bak,il:+v.il,ii:+v.ii,rl:+v.rl,ri:+v.ri,st:"Open",src:"Enterprise",ctl:arr(v.ctl),proc:"grc.risk_review",ent:"",met:"m_grc_risk_app",proj:"",vend:"",svc:"",kri:null,plan:v.plan||"",due:v.due||iso(60),rev:TODAY,exc:"",desc:""};
  X.rk().push(r);X.put("raid_item",r);audit("Risk added",id+" "+v.t);ev_("grc.risk_created","Risk created",{record:id,actor:ME(),detail:v.cat});notify([v.own,v.bak],"You are the owner or backup of new risk "+id,id,"grc.risk_created");toast("Risk "+id+" added","good");sync();closeDrawer();render()}})}
function newFinding(init){init=init||{};openForm({id:"grc_find_new",title:"Log a finding",story:"A finding has a severity, a source, one owner with a different backup and a due date. High findings go to the technical debt ledger.",submit:"Log finding",
 fields:[{k:"t",label:"Finding",type:"text",req:true},{k:"sev",label:"Severity",type:"chips",opts:["Critical","High","Medium","Low"]},{k:"src",label:"Source",type:"select",opts:["Control test","Audit","Self-identified","Third-party review","Incident"]},{k:"own",label:"Owner",type:"people",req:true},{k:"bak",label:"Backup",type:"people",req:true},{k:"due",label:"Due",type:"date",req:true},{k:"ctl",label:"Control",type:"select",opts:[["","None"]].concat(X.ctl().map(c=>[c.id,c.ref+" "+c.t]))},{k:"risk",label:"Risk",type:"select",opts:[["","None"]].concat(X.rk().map(r=>[r.id,r.id+" "+r.t]))}],
 defaults:Object.assign({sev:"Medium",src:"Self-identified",due:iso(30),own:X.who("Theo Marlowe",1),bak:X.who("Avery Chen",2)},init),
 onSubmit:v=>{if(v.own===v.bak){toast("The backup must be a different person","warn");return}const id="FND-"+(111+X.fnd().length-11);const f={id,t:v.t,src:v.src,sref:v.ctl||"-",sev:v.sev,own:v.own,bak:v.bak,due:v.due,st:"Open",ctl:v.ctl||"",risk:v.risk||"",vend:"",steps:[],opened:TODAY,debt:"",desc:""};
  if(v.sev==="High"||v.sev==="Critical"){f.debt=debt("bypass","Finding "+id+": "+v.t,v.sev,v.own,{fix:"Close finding "+id})||"yes"}
  X.fnd().unshift(f);X.put("finding",f);audit("Finding logged",id+" "+v.t);ev_("grc.finding_created","Finding created",{record:id,actor:ME(),detail:v.sev});notify([v.own,v.bak],"New "+v.sev+" finding "+id+" is assigned to you",id,"grc.finding_created");toast("Finding "+id+" logged"+(f.debt?" and added to the debt ledger":""),"good");sync();closeDrawer();render()}})}
function newException(init){init=init||{};openForm({id:"grc_exc_new",title:"Request an exception or risk acceptance",story:"The approver is set by rule: risk acceptance needs the CIO, policy and control exceptions need the domain owner. An approved exception expires and is tracked as technical debt.",submit:"Request approval",
 fields:[{k:"t",label:"What is excepted",type:"text",req:true},{k:"kind",label:"Kind",type:"chips",opts:["Policy exception","Control exception","Risk acceptance"]},{k:"ref",label:"Applies to (policy, control or risk id)",type:"text",req:true},{k:"own",label:"Owner",type:"people",req:true},{k:"bak",label:"Backup",type:"people",req:true},{k:"exp",label:"Expires",type:"date",req:true,help:"No more than 12 months from today"},{k:"why",label:"Reason",type:"longtext",req:true},{k:"comp",label:"Compensating measures",type:"longtext"}],
 defaults:Object.assign({kind:"Policy exception",exp:iso(90),own:X.who("Rina Okafor",0),bak:X.who("Theo Marlowe",1)},init),
 onSubmit:v=>{if(days(v.exp)>366){toast("An exception cannot run longer than 12 months","warn");return}if(days(v.exp)<1){toast("Choose an expiry date in the future","warn");return}if(v.own===v.bak){toast("The backup must be a different person","warn");return}
  const id="EXC-"+(109+X.exc().length-8);const appr=v.kind==="Risk acceptance"?"Casey Rowan":v.kind==="Control exception"?X.who("Rina Okafor",0):X.who("Theo Marlowe",1);
  const e={id,t:v.t,kind:v.kind,ref:v.ref,req:ME(),own:v.own,bak:v.bak,appr,exp:v.exp,st:"Requested",why:v.why,comp:v.comp||"",debt:"",risk:/^GR-/.test(v.ref)?v.ref:"",ctl:/^G[CL]-/.test(v.ref)?v.ref:"",opened:TODAY};
  X.exc().unshift(e);X.put("exception",e);audit("Exception requested",id+" for "+appr);notify([appr],ME()+" asked you to approve "+id+": "+v.t,id,"grc.exception_requested");ev_("grc.exception_requested","Exception requested",{record:id,actor:ME(),detail:appr});toast("Sent to "+appr+" for approval","good");sync();closeDrawer();render()}})}
function recordTest(cid){const c=X.ctlById(cid);if(!c)return;openForm({id:"grc_test",title:"Record test result: "+c.ref,story:"The result updates the control, the Q4 cycle and control coverage. An ineffective result offers a finding.",submit:"Record result",
 fields:[{k:"res",label:"Result",type:"chips",opts:["Effective","Exceptions noted","Ineffective"]},{k:"tester",label:"Tested by",type:"people",req:true,help:"Not the control owner"},{k:"notes",label:"What was tested",type:"longtext",req:true},{k:"ev",label:"Evidence (record id, for example CHG0312)",type:"text"}],defaults:{res:"Effective",tester:c.bak},
 onSubmit:v=>{if(v.tester===c.own){toast("The tester must be someone other than the control owner","warn");return}
  if(v.ev&&!R.resolve(v.ev)&&!G(()=>ZLINK.universe().has(v.ev),false)&&!/^scr:/.test(v.ev)){toast("That is not a record id. Link evidence by record.","warn");return}
  c.last=TODAY;c.res=v.res;if(v.ev)c.ev.push(["Test evidence "+TODAY,v.ev]);X.put("control",c);
  let t=X.tst().find(x=>x.ctl===cid&&x.cycle==="TC-2026Q4");if(!t){t={id:"TST-Q4-"+cid,ctl:cid,cycle:"TC-2026Q4",tester:v.tester,due:iso(14),st:"",res:"",notes:"",ev:[]};X.tst().push(t)}
  t.tester=v.tester;t.res=v.res;t.notes=v.notes;t.st=v.res==="Ineffective"?"Failed":"Passed";if(v.ev)t.ev.push([v.ev,v.ev]);X.put("control_test",t);
  audit("Control test recorded",cid+": "+v.res);ev_("grc.test_recorded","Control test recorded",{record:cid,actor:ME(),detail:v.res});toast("Recorded: "+v.res,v.res==="Effective"?"good":"warn");sync();closeDrawer();render();
  if(v.res==="Ineffective")setTimeout(()=>newFinding({ctl:cid,t:"Control "+c.ref+" is ineffective",src:"Control test",sev:"High",own:c.own,bak:c.bak}),250)}})}
function newRequest(aid){const a=X.aud().find(x=>x.id===aid);if(!a)return;openForm({id:"grc_req",title:"Add an audit request to "+a.id,story:"A request has one owner and a due date. Evidence is linked by record, never uploaded.",submit:"Add request",fields:[{k:"t",label:"What the auditor asked for",type:"text",req:true},{k:"own",label:"Owner",type:"people",req:true},{k:"due",label:"Due",type:"date",req:true}],defaults:{own:a.lead,due:iso(10)},
 onSubmit:v=>{const n=a.reqs.length+1;const r={id:"PBC-"+a.id.slice(-2)+String(n).padStart(2,"0"),t:v.t,own:v.own,due:v.due,st:"Open",ev:[]};a.reqs.push(r);X.put("audit_engagement",a);audit("Audit request added",r.id+" "+v.t);notify([v.own],"New audit request "+r.id+": "+v.t,a.id,"grc.audit_request");toast("Request "+r.id+" added","good");closeDrawer();render()}})}
function assessVendor(vid){const v0=X.ven()[vid];if(!v0)return;v0.dom=v0.dom||{};const vv=G(()=>X.vlist().find(x=>x.id===vid),{n:vid});openForm({id:"grc_va",title:"Record assessment: "+vv.n,story:"Scores for five domains give the overall score. The next assessment date follows the tier (Tier 1 yearly, Tier 2 every 18 months, Tier 3 every 3 years) and must fall before the contract renewal.",submit:"Record assessment",
 fields:[{k:"sec",label:"Security (0 to 100)",type:"number"},{k:"pri",label:"Privacy",type:"number"},{k:"fin",label:"Financial stability",type:"number"},{k:"con",label:"Continuity",type:"number"},{k:"com",label:"Compliance",type:"number"},{k:"tier",label:"Tier",type:"chips",opts:["1","2","3"]},{k:"note",label:"Notes",type:"longtext"}],defaults:{sec:v0.dom.Security||70,pri:v0.dom.Privacy||70,fin:v0.dom.Financial||70,con:v0.dom.Continuity||70,com:v0.dom.Compliance||70,tier:String(v0.tier)},
 live:v=>{const s=Math.round((+v.sec+ +v.pri+ +v.fin+ +v.con+ +v.com)/5);return `<p class="small"><b>Overall ${s}</b>: ${s>=80?"low residual risk":s>=65?"moderate; document follow-ups":"high; needs a finding and an exit or improvement plan"}.</p>`},
 onSubmit:v=>{const s=Math.round((+v.sec+ +v.pri+ +v.fin+ +v.con+ +v.com)/5);v0.dom={Security:+v.sec,Privacy:+v.pri,Financial:+v.fin,Continuity:+v.con,Compliance:+v.com};v0.score=s;v0.tier=+v.tier;v0.last=TODAY;v0.note=v.note||"";X.put("assessment",v0);
  audit("Vendor assessment recorded",vid+": "+s);ev_("grc.vendor_assessed","Vendor assessed",{record:vid,actor:ME(),detail:String(s)});toast("Assessment recorded: "+s,"good");sync();closeDrawer();render();
  if(s<65)setTimeout(()=>newFinding({vend:vid,t:vv.n+" scored "+s+" in its assessment",src:"Third-party review",sev:"High",own:vv.own,bak:X.isCore()?"Camille Ortega":(vv.bak||X.who("",1))}),250)}})}

/* ------------------------------------------------------------------ delegated clicks ------------------------------------------------------------------ */
document.addEventListener("click",e=>{
 const t=e.target;let b;
 if((b=t.closest("[data-grc-open]"))){const p=b.dataset.grcOpen.split(":");R.open(p[0],p.slice(1).join(":"));return}
 if((b=t.closest("[data-grc-new]"))){const k=b.dataset.grcNew;if(k==="risk")newRisk();else if(k==="finding")newFinding();else if(k==="exception")newException();else if(k==="request")newRequest(b.dataset.aud||"AUD-2026-01");return}
 if((b=t.closest("[data-grc-f]"))){const p=b.dataset.grcF.split("|");const m=p[0];if(m==="cat")GS.rf.cat=GS.rf.cat===p[1]?"":p[1];else if(m==="src")GS.rf.src=GS.rf.src===p[1]?"":p[1];else if(m==="hm")GS.hm=p[1];else if(m==="cell")GS.cell=GS.cell===p[1]?null:p[1];else if(m==="fst")GS.ff.st=GS.ff.st===p[1]?"":p[1];else if(m==="fsev")GS.ff.sev=GS.ff.sev===p[1]?"":p[1];else if(m==="xf")GS.xf=GS.xf===p[1]?"":p[1];else if(m==="tab")GS.tab[p[1]]=+p[2];render();return}
 if((b=t.closest("[data-grc-step]"))){const p=b.dataset.grcStep.split(":");const f=X.fnd().find(x=>x.id===p[0]);if(f&&f.steps[+p[1]]){f.steps[+p[1]].done=true;X.put("finding",f);audit("Finding step done",f.id+": "+f.steps[+p[1]].n);toast("Step done","good");sync();R.repaint();render()}return}
 if((b=t.closest("[data-grc-prov]"))){const p=b.dataset.grcProv.split(":");const a=X.aud().find(x=>x.id===p[0]);const r=a&&a.reqs.find(x=>x.id===p[1]);if(r){if(!r.ev.length){toast("Link at least one evidence record first","warn");return}r.st="Provided";X.put("audit_engagement",a);audit("Audit request provided",r.id);ev_("grc.audit_request_provided","Audit request provided",{record:r.id,actor:ME(),detail:a.id});toast(r.id+" marked provided","good");sync();R.repaint();render()}return}
 if((b=t.closest("[data-grc-evl]"))){const p=b.dataset.grcEvl.split(":");const a=X.aud().find(x=>x.id===p[0]);const r=a&&a.reqs.find(x=>x.id===p[1]);if(!r)return;
  openForm({id:"grc_evl",title:"Link evidence to "+r.id,story:"Evidence is a link to a record that already exists, so the auditor sees the same source you do.",submit:"Link evidence",fields:[{k:"id",label:"Record id (for example CHG0312, INC0412, CT-107)",type:"text",req:true},{k:"l",label:"Label",type:"text"}],
   onSubmit:v=>{if(!R.resolve(v.id)&&!G(()=>ZLINK.universe().has(v.id),false)){toast("No record with that id","warn");return}r.ev.push([v.l||v.id,v.id]);X.put("audit_engagement",a);audit("Audit evidence linked",r.id+" to "+v.id);toast("Evidence linked","good");closeDrawer();render();setTimeout(()=>R.open("audit",a.id),200)}});return}
 if((b=t.closest("[data-grc-att]"))){const x=X.attList().find(q=>q.id===b.dataset.grcAtt);if(!x)return;if(b.dataset.act==="attest"){x.st="Attested";x.at=TODAY;X.put("attestation",x);audit("Attested",x.person);ev_("grc.attestation_done","Attestation completed",{record:x.id,actor:ME(),detail:x.person});toast("Attested for "+x.person,"good");sync()}else{notify([x.person],"Please attest your controls for Q4 (due "+iso(21)+")",x.id,"grc.attest_reminder");toast("Reminder sent to "+x.person,"good")}render();return}
 if((b=t.closest("[data-grc-remind-all]"))){const p=X.attList().filter(a=>a.st!=="Attested");notify(p.map(a=>a.person),"Please attest your controls for Q4",  "ATT-2026Q4","grc.attest_reminder");toast("Reminders sent to "+p.length+" owners","good");return}
 if((b=t.closest("[data-grc-test]"))){recordTest(b.dataset.grcTest);return}
 if((b=t.closest("[data-grc-assess]"))){assessVendor(b.dataset.grcAssess);return}
 if((b=t.closest("[data-grc-go]"))){go(b.dataset.grcGo);return}
});

/* ------------------------------------------------------------------ screens ------------------------------------------------------------------ */
const fwOf=c=>arr(c.maps).map(m=>m.split(":")[0]).filter((x,i,a)=>a.indexOf(x)===i);
function heatMap(){const rs=X.allRisks().filter(r=>r.st!=="Closed");const key=GS.hm==="inh"?"inh":"res";const L=r=>GS.hm==="inh"?r.il:r.rl,I=r=>GS.hm==="inh"?r.ii:r.ri;
 const cells=[];for(let l=5;l>=1;l--){for(let i=1;i<=5;i++){const here=rs.filter(r=>L(r)===l&&I(r)===i);const b=X.band(l*i);const k=l+"x"+i;cells.push(`<button type="button" class="grc-hc ${b[0]}${GS.cell===k?" sel":""}" data-grc-f="cell|${k}" aria-pressed="${GS.cell===k}" aria-label="Likelihood ${l}, impact ${i}, ${here.length} risks, ${b[1]}">${here.length?`<b>${here.length}</b>`:""}<small>${l*i}</small></button>`)}}
 return `<div class="grc-hm"><div class="grc-hm-y" aria-hidden="true">Likelihood</div><div class="grc-hm-g" role="group" aria-label="Risk heat map, ${GS.hm==="inh"?"inherent":"residual"} scores">${cells.join("")}</div><div class="grc-hm-x" aria-hidden="true">Impact</div></div>`}
function riskRows(){const rs=X.allRisks();const f=GS.rf;return rs.filter(r=>(!f.cat||r.cat===f.cat)&&(!f.src||r.src===f.src)&&(!GS.cell||(()=>{const p=GS.cell.split("x");return (GS.hm==="inh"?r.il:r.rl)===+p[0]&&(GS.hm==="inh"?r.ii:r.ri)===+p[1]})())&&r.st!=="Closed").sort((a,b)=>b.res-a.res)}
const riskCols=[{h:"Risk",f:r=>`${openB("risk",r.id,r.id)}<br><span class="small">${H(r.t)}</span>`},{h:"Category",f:r=>H(r.cat)},{h:"Owner",f:r=>ppl(r.own)},{h:"Backup",f:r=>bk(r.bak)},{h:"Inherent",f:r=>sc(r.il,r.ii)},{h:"Residual",f:r=>sc(r.rl,r.ri)},{h:"Appetite",f:r=>X.app()[r.cat]==null?pill("Not set"):X.aboveAppetite(r)?pill("Above ("+X.app()[r.cat]+")","bad"):pill("Within","good")},{h:"Status",f:r=>pill(r.st,r.st==="Treating"?"info":r.st==="Accepted"?"mute":"warn")},{h:"Source",f:r=>H(r.src)},{h:"Controls",f:r=>arr(r.ctl).length||'<span class="muted">-</span>'}];
function trace(){const rs=X.rk().filter(r=>X.aboveAppetite(Object.assign({},r,{res:X.score(r.rl,r.ri)}))||r.st==="Treating").slice(0,6);
 return tbl([{h:"Risk",f:r=>openB("risk",r.id,r.id+" "+r.t.slice(0,40))},{h:"Controls",f:r=>arr(r.ctl).map(c=>link(c,c)).join(" ")||"-"},{h:"Process",f:r=>r.proc?`<button class="rsh-link" data-grc-go="plat_proc">${H(r.proc)}</button>`:"-"},{h:"Entity",f:r=>H(r.ent||"-")},{h:"Metric",f:r=>r.met&&X.hasMetric(r.met)&&METRICS[r.met]?fc(r.met):"-"},{h:"Owner and backup",f:r=>ppl(r.own)+" "+bk(r.bak)}],rs)}

function homeScreen(){const s=sync();const cs=X.ctl();
 const attn=[];
 X.fnd().filter(X.overdue).sort((a,b)=>days(a.due)-days(b.due)).forEach(f=>attn.push(["bad","Finding overdue",openB("finding",f.id,f.id+" "+f.t),Math.abs(days(f.due))+" days late, "+f.own]));
 X.exc().filter(e=>["Expiring","Expired"].includes(X.excState(e))).forEach(e=>attn.push([X.excState(e)==="Expired"?"bad":"warn","Exception "+X.excState(e).toLowerCase(),openB("exception",e.id,e.id+" "+e.t),"expires "+date(e.exp)+", approver "+e.appr]));
 Object.values(X.ven()).filter(v=>X.vStatus(v)[0]!=="good").forEach(v=>attn.push([X.vStatus(v)[0],"Vendor assessment",openB("vendor",v.id,G(()=>X.vlist().find(x=>x.id===v.id).n,v.id)),"Tier "+v.tier+", "+X.vStatus(v)[1].toLowerCase()]));
 X.pol().filter(X.polDue).forEach(p=>attn.push(["warn","Policy review due",openB("policy",p.id,p.id+" "+p.t),"review "+date(p.nextRev)]));
 X.aud().forEach(a=>a.reqs.filter(r=>r.st==="Overdue").forEach(r=>attn.push(["bad","Audit request overdue",openB("audit",a.id,r.id+" "+r.t),a.id+", "+r.own])));
 const fwRows=FWS().map(fw=>{const l=cs.filter(c=>fwOf(c).includes(fw));const cur=l.filter(X.testCurrent).length;return{fw,n:l.length,cur,pct:l.length?Math.round(100*cur/l.length):0}});
 return `<div class="screen grc">${hero("Governance, risk and compliance","One view of risk, controls and assurance",`<b>${s.above}</b> of ${s.risks} risks are above appetite. Control coverage is <b>${s.cov}%</b> (${s.covered} of ${s.ctl}). <b>${s.od}</b> findings are overdue and <b>${s.exp30}</b> exceptions are expiring or expired. Attestation is <b>${s.att}%</b> complete.`,`<div class="row"><button class="btn primary" data-grc-new="risk">Add a risk</button><button class="btn" data-grc-new="finding">Log a finding</button><button class="btn" data-grc-new="exception">Request an exception</button></div>`)}${lensNote()}
 ${KR([["Risks above appetite",s.above,"of "+s.risks+" in the register",{metric:"m_grc_risk_app",keep:true}],["Control coverage",s.cov+"%",s.covered+" of "+s.ctl+" controls",{metric:"m_grc_ctl_cov"}],["Overdue findings",s.od,s.openF+" open",{metric:"m_grc_find_od",keep:true}],["Attestation completion",s.att+"%","Q4 cycle, due "+date(iso(21)),{metric:"m_grc_att_rate"}],["Exceptions expiring or expired",s.exp30,"within 30 days",{metric:"m_grc_exc_exp",keep:true}],["Tier 1 vendors assessed",s.ven1pct+"%",s.ven1ok+" of "+s.ven1,{metric:"m_grc_ven_t1"}]])}
 <div class="grc-two">${card("Residual risk heat map","Each cell counts risks at that likelihood and impact. Click a cell to list them in the Risk register.",`<div class="row" style="gap:8px;margin-bottom:10px">${chips([["res","Residual"],["inh","Inherent"]],GS.hm,"data-grc-hmx")}</div>${heatMap()}${legend([["Low (1 to 4)","--good"],["Moderate (5 to 9)","--info-f"],["High (10 to 14)","--warn"],["Critical (15 to 25)","--bad"]])}<button class="btn" data-grc-go="grc_risk">Open the Risk register</button>`)}
 ${card("Needs attention","Overdue, expiring or due items across all registers, most urgent first.",attn.length?tbl([{h:"What",f:a=>pill(a[1],a[0])},{h:"Record",f:a=>a[2]},{h:"Detail",f:a=>H(a[3])}],attn.slice(0,9)):'<p class="muted">Nothing is overdue.</p>')}</div>
 <div class="grc-two">${card("Control coverage by framework","Controls mapped to each framework with a current test. Names are generic labels, not certifications.",fwRows.map(r=>`<div class="grc-fw"><span>${H(r.fw)}</span>${bar(r.pct,r.pct<60?"warn":"good")}<b>${r.cur} of ${U.esc(r.n)}</b></div>`).join("")+`<button class="btn" data-grc-go="grc_ctl">Open Controls and testing</button>`,fc("m_grc_ctl_cov"))}
 ${card("Traceability: risk to control to process to entity to metric to owner","Every risk names the controls that treat it, the process that manages it, the data entity and metric that measure it, and a named owner with a backup.",trace())}</div>
 <p class="muted small">Project risks (RK) and RAID risks (R) are read from the Risk heat map and the RAID log and shown in the same register; this suite does not copy them.</p>
 ${procCard("grc_home")}</div>`}

function riskScreen(){const s=sync();const rows=riskRows();const cats=X.cats().filter(c=>X.allRisks().some(r=>r.cat===c));
 const tabs=[`${KR([["Risks in the register",s.risks,"enterprise, project and RAID"],["Above appetite",s.above,"residual over the category limit",{metric:"m_grc_risk_app",keep:true}],["Critical residual",X.allRisks().filter(r=>r.res>=15&&r.st!=="Closed").length,"score 15 or more",{keep:true}],["Accepted",X.allRisks().filter(r=>r.st==="Accepted").length,"with an approved exception",{keep:true}]])}
  <div class="grc-two">${card("Heat map","Click a cell to filter the register.",`<div class="row" style="gap:8px;margin-bottom:10px">${[["res","Residual"],["inh","Inherent"]].map(c=>`<button type="button" class="chip${GS.hm===c[0]?" on":""}" data-grc-f="hm|${c[0]}" aria-pressed="${GS.hm===c[0]}">${c[1]}</button>`).join("")}</div>${heatMap()}${legend([["Low","--good"],["Moderate","--info-f"],["High","--warn"],["Critical","--bad"]])}`)}
  ${card("Appetite by category","Residual limit for each category and how many risks exceed it.",tbl([{h:"Category",f:c=>H(c)},{h:"Appetite limit",f:c=>X.app()[c]},{h:"Risks",f:c=>X.allRisks().filter(r=>r.cat===c&&r.st!=="Closed").length},{h:"Above",f:c=>{const n=X.allRisks().filter(r=>r.cat===c&&X.aboveAppetite(r)).length;return n?pill(n,"bad"):pill("0","good")}}],cats))}</div>`,
  `<div class="row grc-filters">${chips(cats.map(c=>[c,c]),GS.rf.cat,"data-grc-fx-cat")}</div>`.replace(/data-grc-fx-cat="([^"]*)"/g,'data-grc-f="cat|$1"')+`<div class="row grc-filters">${chips([["Enterprise","Enterprise"],["Project risk","Project risk"],["Project RAID","Project RAID"]],GS.rf.src,"data-grc-fx-src")}</div>`.replace(/data-grc-fx-src="([^"]*)"/g,'data-grc-f="src|$1"')+(GS.cell?`<p class="small">Showing likelihood ${GS.cell.split("x")[0]}, impact ${GS.cell.split("x")[1]} <button class="btn quiet sm" data-grc-f="cell|${GS.cell}">Clear</button></p>`:"")+card("Risk register",rows.length+" risks, highest residual first. Open one for controls, findings, history and comments.",tbl(riskCols,rows),`<button class="btn primary" data-grc-new="risk">Add a risk</button>`)];
 return `<div class="screen grc">${hero(TM("risk",{cap:1})+" register","Enterprise and project risks on one scale",`<b>${s.above}</b> of ${s.risks} risks are above appetite. Project risks from the risk simulation and the RAID log appear here without copies.`,`<div class="row">${fc("m_grc_risk_app")}<button class="btn primary" data-grc-new="risk">Add a risk</button></div>`)}${lensNote()}${views("grc_risk",["Dashboard","Register"],tabs)}${procCard("grc_risk")}</div>`}

function ctlScreen(){const s=sync();const cs=X.ctl();const T=X.tst();const cyc=X.cycles[1];
 const byst=st=>T.filter(t=>t.st===st).length;
 const cov=`${KR([["Control coverage",s.cov+"%",s.covered+" of "+s.ctl,{metric:"m_grc_ctl_cov"}],["Tested this cycle",s.testsDone+" of "+s.tests,"Q4 cycle",{keep:true}],["Ineffective",cs.filter(c=>c.res==="Ineffective").length,"last test result",{keep:true}],["Never tested or stale",cs.filter(c=>!X.testCurrent(c)).length,"past their test date",{keep:true}]])}
  ${card("Coverage by framework","A control counts as covered when it has an owner, a backup, a framework mapping and a test inside its frequency.",tbl([{h:"Framework",f:r=>H(r.fw)},{h:"Controls mapped",f:r=>r.n},{h:"Tested and current",f:r=>r.cur+" of "+r.n},{h:"Coverage",f:r=>bar(r.p,r.p<60?"warn":"good")+" "+r.p+"%"},{h:"Failing",f:r=>r.fail?pill(r.fail,"bad"):pill("0","good")}],FWS().map(fw=>{const l=cs.filter(c=>fwOf(c).includes(fw));const cur=l.filter(X.testCurrent).length;return{fw,n:l.length,cur,p:l.length?Math.round(100*cur/l.length):0,fail:l.filter(c=>c.res==="Ineffective").length}})),fc("m_grc_ctl_cov"))}
  ${card("Controls without a current test","Past their test date or never tested, longest first.",tbl([{h:"Control",f:c=>openB("control",c.id,c.ref)},{h:"What it does",f:c=>H(c.t)},{h:"Owner",f:c=>ppl(c.own)},{h:"Last tested",f:c=>c.res==="Not tested"?pill("Never","bad"):H(date(c.last))},{h:"Was due",f:c=>H(date(X.nextDue(c)))},{h:"",f:c=>`<button class="btn quiet sm" data-grc-test="${c.id}">Record result</button>`}],cs.filter(c=>!X.testCurrent(c)).sort((a,b)=>days(X.nextDue(a))-days(X.nextDue(b))).slice(0,8)))}`;
 const lib=`${card("Control library","One list: the library controls from Audit trail and retention plus internal controls. Frameworks are generic names.",`<div class="row grc-filters">${chips(FWS().map(f=>[f,f]),GS.xf,"data-grc-fx")}</div>`.replace(/data-grc-fx="([^"]*)"/g,'data-grc-f="xf|$1"')+tbl([{h:"Control",f:c=>`${openB("control",c.id,c.ref)}<br><span class="small">${H(c.t)}</span>`},{h:"Mapped to",f:c=>fwOf(c).map(f=>pill(f,"info")).join(" ")},{h:"Owner",f:c=>ppl(c.own)},{h:"Backup",f:c=>bk(c.bak)},{h:"Frequency",f:c=>H(c.freq)},{h:"Last result",f:c=>pill(c.res,c.res==="Effective"?"good":c.res==="Not tested"?"mute":c.res==="Ineffective"?"bad":"warn")},{h:"Next test",f:c=>dueChip(X.nextDue(c))},{h:"Risks",f:c=>arr(c.risks).length||"-"},{h:"Evidence",f:c=>c.ev.length||'<span class="muted">0</span>'}],cs.filter(c=>!GS.xf||fwOf(c).includes(GS.xf))))}`;
 const stOrder=["Not started","In testing","Evidence requested","Passed","Failed"];
 const cycle=`${kpiRow(stOrder.map(st=>[st,byst(st),"tests",{keep:true}]))}${card(cyc.name,date(cyc.start)+" to "+date(cyc.end)+". Testers are never the control owner.",tbl([{h:"Control",f:t=>{const c=X.ctlById(t.ctl);return c?`${openB("control",c.id,c.ref)}<br><span class="small">${H(c.t)}</span>`:H(t.ctl)}},{h:"Tester",f:t=>ppl(t.tester)},{h:"Due",f:t=>dueChip(t.due,t.st==="Passed"||t.st==="Failed")},{h:"Status",f:t=>pill(t.st,t.st==="Passed"?"good":t.st==="Failed"?"bad":t.st==="Evidence requested"?"warn":"mute")},{h:"Result and notes",f:t=>H((t.res?t.res+". ":"")+t.notes)},{h:"Evidence links",f:t=>arr(t.ev).map(e=>link(e[1],e[0])).join(", ")||"-"},{h:"",f:t=>t.st==="Passed"||t.st==="Failed"?"":`<button class="btn quiet sm" data-grc-test="${t.ctl}">Record result</button>`}],T.slice().sort((a,b)=>stOrder.indexOf(a.st)-stOrder.indexOf(b.st))))}`;
 const at=X.attList();const done=at.filter(a=>a.st==="Attested").length;
 const att=`${KR([["Attestation completion",X.attRate()+"%",done+" of "+at.length+" owners",{metric:"m_grc_att_rate"}],["Pending",at.filter(a=>a.st==="Pending").length,"due "+date(iso(21)),{keep:true}],["Overdue",at.filter(a=>a.st==="Overdue").length,"escalate to backup",{keep:true}],["Previous cycle","100%","ATT-2026Q3 closed "+date(iso(-12)),{keep:true}]])}${card("Q4 control owner attestation","Each owner confirms their controls operated as described. Overdue attestations go to the owner's backup.",tbl([{h:"Owner",f:a=>ppl(a.person)},{h:"Backup",f:a=>bk(G(()=>X.ctlById(a.ctls[0]).bak,""))},{h:"Controls",f:a=>a.ctls.map(c=>link(c,c)).join(" ")},{h:"Status",f:a=>pill(a.st,a.st==="Attested"?"good":a.st==="Overdue"?"bad":"warn")},{h:"Attested on",f:a=>a.at?H(date(a.at)):"-"},{h:"",f:a=>a.st==="Attested"?"":(a.person===ME()?`<button class="btn primary sm" data-grc-att="${a.id}" data-act="attest">Attest</button>`:`<button class="btn quiet sm" data-grc-att="${a.id}" data-act="remind">Remind</button> <button class="btn quiet sm" data-grc-att="${a.id}" data-act="attest" title="Record on behalf of the owner">Record</button>`)}],at),`<button class="btn" data-grc-remind-all>Remind everyone pending</button>`)}`;
 return `<div class="screen grc">${hero(TM("control",{many:1,cap:1})+" and testing","Controls mapped to frameworks, tested every cycle",`Control coverage is <b>${s.cov}%</b>. <b>${s.testsDone}</b> of ${s.tests} Q4 tests are done; <b>${byst("Failed")}</b> failed. Attestation is <b>${s.att}%</b> complete.`,`<div class="row">${fc("m_grc_ctl_cov")}${fc("m_grc_att_rate")}</div>`)}${lensNote()}${views("grc_ctl",["Coverage","Library","Test cycle","Attestation"],[cov,lib,cycle,att])}${procCard("grc_ctl")}</div>`}

function findScreen(){const s=sync();const fs=X.fnd();const f=GS.ff;const rows=fs.filter(x=>(!f.st||x.st===f.st)&&(!f.sev||x.sev===f.sev));
 const dash=`${KR([["Open findings",s.openF,fs.length+" total",{keep:true}],["Overdue",s.od,"past due date",{metric:"m_grc_find_od",keep:true}],["High or critical",fs.filter(x=>X.open(x)&&(x.sev==="High"||x.sev==="Critical")).length,"open",{keep:true}],["In the debt ledger",fs.filter(x=>x.debt).length,"technical debt",{keep:true}]])}`;
 return `<div class="screen grc">${hero("Issues and "+TM("finding",{many:1}),"Every finding has a plan, an owner and a date",`<b>${s.od}</b> of ${s.openF} open findings are overdue. Findings come from control tests, audits, third-party reviews and self-identification.`,`<div class="row">${fc("m_grc_find_od")}<button class="btn primary" data-grc-new="finding">Log a finding</button></div>`)}${lensNote()}${dash}
 ${card("Findings","Filter by status or severity. Open a finding for the remediation plan, comments and history.",`<div class="row grc-filters">${chips(["Open","Plan approved","In remediation","Ready to validate","Closed"].map(x=>[x,x]),f.st,"data-grc-fx")}</div>`.replace(/data-grc-fx="([^"]*)"/g,'data-grc-f="fst|$1"')+`<div class="row grc-filters">${chips(["Critical","High","Medium","Low"].map(x=>[x,x]),f.sev,"data-grc-fx")}</div>`.replace(/data-grc-fx="([^"]*)"/g,'data-grc-f="fsev|$1"')+tbl([{h:"Finding",f:x=>`${openB("finding",x.id,x.id)}<br><span class="small">${H(x.t)}</span>`},{h:"Severity",f:x=>pill(x.sev,x.sev==="High"||x.sev==="Critical"?"bad":x.sev==="Medium"?"warn":"mute")},{h:"Source",f:x=>H(x.src)},{h:"Control or risk",f:x=>[x.ctl&&link(x.ctl,x.ctl),x.risk&&link(x.risk,x.risk)].filter(Boolean).join(" ")||"-"},{h:"Owner",f:x=>ppl(x.own)},{h:"Backup",f:x=>bk(x.bak)},{h:"Due",f:x=>dueChip(x.due,x.st==="Closed")},{h:"Status",f:x=>pill(x.st,x.st==="Closed"?"good":"info")},{h:"Plan",f:x=>x.steps.length?x.steps.filter(q=>q.done).length+" of "+x.steps.length:'<span class="muted">none</span>'}],rows),`<button class="btn primary" data-grc-new="finding">Log a finding</button>`)}
 ${procCard("grc_find")}</div>`}

function polScreen(){const s=sync();const ps=X.pol();
 return `<div class="screen grc">${hero(TM("policy",{many:1,cap:1}),"Versioned policies with acknowledgement",`<b>${s.pol}</b> policies; <b>${s.polDue}</b> due for review within 30 days. Acknowledgement is <b>${s.ack}%</b> across published policies.`,`<div class="row">${fc("m_grc_pol_ack")}</div>`)}${lensNote()}
 ${KR([["Policies",s.pol,"in the library",{keep:true}],["Due for review",s.polDue,"within 30 days",{keep:true}],["Acknowledgement",s.ack+"%","published policies",{metric:"m_grc_pol_ack"}],["In draft or review",ps.filter(p=>p.vers[0].st!=="Published").length,"new versions",{keep:true}]])}
 ${card("Policy library","Open a policy for version history, the controls that enforce it, exceptions and acknowledgement.",tbl([{h:"Policy",f:p=>`${openB("policy",p.id,p.id)}<br><span class="small">${H(p.t)}</span>`},{h:"Version",f:p=>"v"+H(p.vers[0].v)+" "+pill(p.vers[0].st,p.vers[0].st==="Published"?"good":"info")},{h:"Owner",f:p=>ppl(p.own)},{h:"Backup",f:p=>bk(p.bak)},{h:"Next review",f:p=>dueChip(p.nextRev)},{h:"Acknowledged",f:p=>bar(X.polAckRate(p),X.polAckRate(p)<80?"warn":"good")+" "+p.done+" of "+p.req},{h:"Frameworks",f:p=>p.fw.map(f=>pill(f,"info")).join(" ")},{h:"Controls",f:p=>arr(p.ctl).length}],ps))}
 ${procCard("grc_pol")}</div>`}

function audScreen(){const s=sync();const au=X.aud();const reqs=au.flatMap(a=>a.reqs.map(r=>Object.assign({aud:a.id},r))).filter(X.reqOpen).sort((a,b)=>days(a.due)-days(b.due));
 return `<div class="screen grc">${hero(TM("audit",{cap:1})+" management","Engagements, requests and evidence in one place",`<b>${au.length}</b> engagements; <b>${s.reqOpen}</b> requests are open. Evidence is linked to existing records, never uploaded.`,`<div class="row">${fc("m_grc_audit_req")}<button class="btn primary" data-grc-new="request">Add an audit request</button></div>`)}${lensNote()}
 ${KR([["Engagements",au.length,au.filter(a=>a.st!=="Closed").length+" active",{keep:true}],["Open requests",s.reqOpen,"awaiting the owner",{keep:true}],["Overdue requests",au.reduce((n,a)=>n+a.reqs.filter(r=>r.st==="Overdue").length,0),"escalate to the backup",{keep:true}],["Findings from audits",X.fnd().filter(f=>/^AUD-/.test(f.sref)).length,"in Issues and findings",{keep:true}]])}
 <div class="grid g2 grc-cards">${au.map(a=>{const open=a.reqs.filter(X.reqOpen).length;return `<section class="card glass"><div class="cardhead"><div><h3>${openB("audit",a.id,a.id)}</h3><span class="muted small">${H(a.t)}</span></div>${pill(a.st,a.st==="Fieldwork"?"warn":a.st==="Closed"?"good":"info")}</div><dl class="grc-kv"><div><dt>Auditor</dt><dd>${H(a.firm)}</dd></div><div><dt>Lead and backup</dt><dd>${ppl(a.lead)} ${bk(a.bak)}</dd></div><div><dt>Period</dt><dd>${H(a.period)}</dd></div><div><dt>Report due</dt><dd>${dueChip(a.report)}</dd></div><div><dt>Requests</dt><dd>${a.reqs.length-open} of ${a.reqs.length} provided</dd></div><div><dt>Controls in scope</dt><dd>${a.ctl.length}</dd></div></dl></section>`}).join("")}</div>
 ${card("Open requests","Across engagements, soonest due first.",tbl([{h:"Request",f:r=>`<b>${H(r.id)}</b> ${H(r.t)}`},{h:"Engagement",f:r=>openB("audit",r.aud,r.aud)},{h:"Owner",f:r=>ppl(r.own)},{h:"Due",f:r=>dueChip(r.due)},{h:"Status",f:r=>pill(r.st,r.st==="Overdue"?"bad":"warn")},{h:"Evidence",f:r=>r.ev.length?r.ev.map(e=>link(e[1],e[0])).join(", "):'<span class="muted">none yet</span>'}],reqs))}
 ${procCard("grc_aud")}</div>`}

function venScreen(){const s=sync();const V=X.vlist();const con=X.contracts();
 const rows=V.map(v=>({v,t:X.ven()[v.id]})).filter(x=>x.t).sort((a,b)=>a.t.tier-b.t.tier||b.t.inh.localeCompare(a.t.inh));
 const ren=con.map(c=>({c,t:X.ven()[c.v]})).filter(x=>x.t).sort((a,b)=>new Date(a.c.rn)-new Date(b.c.rn)).slice(0,9);
 return `<div class="screen grc">${hero("Third-party risk","Tiers, assessments and renewals together",`<b>${s.ven1ok}</b> of ${s.ven1} Tier 1 vendors have a current assessment. Every contract renewal below shows whether the vendor's assessment will be current when it renews.`,`<div class="row">${fc("m_grc_ven_t1")}</div>`)}${lensNote()}
 ${KR([["Vendors in scope",rows.length,"tiered by criticality",{keep:true}],["Tier 1 current",s.ven1pct+"%",s.ven1ok+" of "+s.ven1,{metric:"m_grc_ven_t1"}],["Overdue or not assessed",rows.filter(x=>X.vStatus(x.t)[0]==="bad").length,"needs an assessment",{keep:true}],["Open vendor findings",X.fnd().filter(f=>f.vend&&X.open(f)).length,"in Issues and findings",{keep:true}]])}
 ${card("Vendors by tier","Tier 1 vendors are critical to publishing or hold member data. Assessment frequency follows the tier.",tbl([{h:"Vendor",f:x=>`${openB("vendor",x.v.id,x.v.n)}<br><span class="small">${H(x.t.data)}</span>`},{h:"Tier",f:x=>pill("Tier "+x.t.tier,x.t.tier===1?"bad":x.t.tier===2?"warn":"mute")},{h:"Inherent risk",f:x=>pill(x.t.inh,x.t.inh==="High"?"bad":x.t.inh==="Medium"?"warn":"good")},{h:"Assessment score",f:x=>x.t.last?bar(x.t.score,x.t.score<65?"bad":x.t.score<80?"warn":"good")+" "+x.t.score:'<span class="muted">none</span>'},{h:"Last assessed",f:x=>x.t.last?H(date(x.t.last)):pill("Never","bad")},{h:"Status",f:x=>{const st=X.vStatus(x.t);return pill(st[1],st[0])}},{h:"Owner",f:x=>ppl(x.v.own)},{h:"Backup",f:x=>bk(!X.isCore()?x.v.bak:G(()=>ORGX.domainView("vendor").backup.name,"")===x.v.own?"Avery Chen":G(()=>ORGX.domainView("vendor").backup.name,""))},{h:"Findings",f:x=>x.t.findings.map(f=>link(f,f)).join(" ")||"-"},{h:"",f:x=>`<button class="btn quiet sm" data-grc-assess="${x.v.id}">Record assessment</button>`}],rows))}
 ${card("Contract renewals and budget lines","A renewal needs a current assessment first. Contracts and budget lines come from Vendors and contracts; nothing is copied.",tbl([{h:"Contract",f:x=>`${openB("contract",x.c.id,x.c.id)}<br><span class="small">${H(x.c.n)}</span>`},{h:"Vendor",f:x=>H(G(()=>X.vlist().find(v=>v.id===x.c.v).n,x.c.v))},{h:"Renews",f:x=>dueChip(x.c.rn)},{h:"Assessment at renewal",f:x=>{const due=x.t.last?X.vAssessDue(x.t):iso(-1);const ok=x.t.last&&new Date(due)>=new Date(x.c.rn);return ok?pill("Current at renewal","good"):pill(x.t.last?"Due "+date(due):"Not assessed","bad")}},{h:"Annual value",f:x=>G(()=>money(x.c.ann),x.c.ann)},{h:"Budget line",f:x=>link(String(x.c.line).replace(/^Run budget /,""),String(x.c.line))},{h:"Contract owner",f:x=>ppl(x.c.own)}],ren))}
 ${procCard("grc_ven")}</div>`}

function excScreen(){const s=sync();const ex=X.exc().slice().sort((a,b)=>({Expired:0,Expiring:1,Requested:2,Approved:3,Rejected:4,Closed:5}[X.excState(a)]-{Expired:0,Expiring:1,Requested:2,Approved:3,Rejected:4,Closed:5}[X.excState(b)])||new Date(a.exp)-new Date(b.exp));
 const act=ex.filter(X.excOpen);
 const tl=act.filter(e=>X.excState(e)!=="Requested").map(e=>{const d=days(e.exp);const p=Math.max(0,Math.min(100,Math.round(100*(d+30)/210)));return `<div class="grc-tl"><span class="grc-tl-l">${openB("exception",e.id,e.id)}</span><span class="grc-tl-t"><i class="${d<0?"bad":d<=30?"warn":"good"}" style="width:${p}%"></i></span><span class="small muted">${d<0?Math.abs(d)+" d past expiry":d+" d left"}</span></div>`}).join("");
 return `<div class="screen grc">${hero("Exceptions and acceptances","Time-limited, approved and tracked as debt",`<b>${act.length}</b> active; <b>${s.exp30}</b> expiring or expired; <b>${ex.filter(e=>e.st==="Requested").length}</b> waiting for approval. Approved exceptions add an item to Technical debt.`,`<div class="row">${fc("m_grc_exc_exp")}<button class="btn primary" data-grc-new="exception">Request an exception</button></div>`)}${lensNote()}
 ${KR([["Active",act.length,"approved or requested",{keep:true}],["Awaiting approval",ex.filter(e=>e.st==="Requested").length,"with the approver",{keep:true}],["Expiring in 30 days",ex.filter(e=>X.excState(e)==="Expiring").length,"renew or close",{keep:true}],["Expired",ex.filter(e=>X.excState(e)==="Expired").length,"still in effect without approval",{metric:"m_grc_exc_exp",keep:true}]])}
 ${card("Time to expiry","Bar length is the time left, scaled from 30 days past expiry to 6 months ahead.",tl+legend([["More than 30 days left","--good"],["Within 30 days","--warn"],["Expired","--bad"]]))}
 ${card("Exception register","Open an exception to approve, reject, renew or close it.",tbl([{h:"Exception",f:e=>`${openB("exception",e.id,e.id)}<br><span class="small">${H(e.t)}</span>`},{h:"Kind",f:e=>H(e.kind)},{h:"Applies to",f:e=>link(e.ref,e.ref)},{h:"Owner",f:e=>ppl(e.own)},{h:"Backup",f:e=>bk(e.bak)},{h:"Approver",f:e=>ppl(e.appr)},{h:"Expires",f:e=>dueChip(e.exp,e.st==="Rejected"||e.st==="Closed")},{h:"State",f:e=>{const st=X.excState(e);return pill(st,st==="Expired"||st==="Rejected"?"bad":st==="Expiring"||st==="Requested"?"warn":"good")}},{h:"Debt item",f:e=>e.debt?H(e.debt):'<span class="muted">on approval</span>'}],ex),`<button class="btn primary" data-grc-new="exception">Request an exception</button>`)}
 ${procCard("grc_exc")}</div>`}

